package com.saludintegral.cita.controller;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import jakarta.validation.Valid;import java.util.*;import com.saludintegral.cita.model.Cita;import com.saludintegral.cita.dto.*;import com.saludintegral.cita.services.CitaService;@RestController @RequestMapping("/api/citas")public class CitaController{final CitaService s;public CitaController(CitaService s){this.s=s;}@GetMapping public List<Cita> all(){return s.all();}@GetMapping("/{id}")public Cita get(@PathVariable Long id){return s.get(id);}@PostMapping public ResponseEntity<Cita> create(@Valid @RequestBody CitaRequest x){return ResponseEntity.status(201).body(s.create(x));}@PatchMapping("/{id}/estado")public Cita estado(@PathVariable Long id,@Valid @RequestBody EstadoRequest x){return s.estado(id,x.estado());}@DeleteMapping("/{id}")public Cita cancelar(@PathVariable Long id){return s.cancelar(id);}}
